-- Empty raw tables with the same columns and types the loader creates.
-- Generated by ci/make_raw_schema.py from the landing zone. Used only by CI.
create schema if not exists raw;

create table if not exists raw.openfigi_mappings (
	input_ticker TEXT,
	input_exch_code TEXT,
	_ingested_at TEXT,
	_source TEXT,
	_batch_id TEXT,
	raw_response TEXT,
	match_status TEXT,
	match_count BIGINT,
	figi TEXT,
	name TEXT,
	ticker TEXT,
	"exchCode" TEXT,
	"compositeFIGI" TEXT,
	"shareClassFIGI" TEXT,
	"securityType" TEXT,
	"securityType2" TEXT,
	"marketSector" TEXT,
	_source_file TEXT,
	ingest_date DATE,
	_loaded_at TIMESTAMP WITH TIME ZONE
);

create table if not exists raw.transactions (
	transaction_id BIGINT,
	security_id TEXT,
	trade_date DATE,
	settlement_date DATE,
	side TEXT,
	quantity BIGINT,
	price FLOAT(53),
	_source_file TEXT,
	ingest_date DATE,
	_loaded_at TIMESTAMP WITH TIME ZONE
);

create table if not exists raw.prices (
	date TEXT,
	close FLOAT(53),
	high FLOAT(53),
	low FLOAT(53),
	open FLOAT(53),
	volume BIGINT,
	"adjClose" FLOAT(53),
	"adjHigh" FLOAT(53),
	"adjLow" FLOAT(53),
	"adjOpen" FLOAT(53),
	"adjVolume" BIGINT,
	"divCash" FLOAT(53),
	"splitFactor" FLOAT(53),
	ticker TEXT,
	_source_file TEXT,
	ingest_date DATE,
	_loaded_at TIMESTAMP WITH TIME ZONE
);

create table if not exists raw.custodian_holdings (
	as_of_date DATE,
	security_id TEXT,
	quantity FLOAT(53),
	_source_file TEXT,
	ingest_date DATE,
	_loaded_at TIMESTAMP WITH TIME ZONE
);

create table if not exists raw.planted_breaks (
	break_id BIGINT,
	break_type TEXT,
	security_id TEXT,
	ticker TEXT,
	transaction_id BIGINT,
	effective_date DATE,
	detail TEXT,
	_source_file TEXT,
	ingest_date DATE,
	_loaded_at TIMESTAMP WITH TIME ZONE
);
